from itertools import product

# c = [c0, c1, 2, c3, c4]
# sum c =5 so c0+c1+c3+c4=3, all >=0 int, <=4

possible = []
for vals in product(range(5), repeat=4):
    c0,c1,c3,c4 = vals
    if c0 + c1 + c3 + c4 != 3: continue
    c = [c0, c1, 2, c3, c4]
    # now count occurrences
    counts = [0]*5
    for val in c:
        if 0 <= val <=4:
            counts[val] +=1
        else:
            break
    else:
        if counts == c:
            possible.append(c)
print(possible)
